import { precTableSize } from '#/lib/precedence'
import {
  PROJECT_NAME_MAX,
  decodeProjectData,
  decodeProjectView,
  defaultProjectView,
  limitText,
  type ProjectData,
  type ProjectView,
} from '#/lib/project'
import { openDatabase, transaction } from './db.server'

export const MAX_DATA_CHARS = 2_000_000
export const LABEL_MAX = 200
const AUTO_SNAPSHOT_EVERY_MS = 20 * 60 * 1000
const KEPT: Record<Exclude<SnapshotKind, 'named'>, number> = { auto: 30, safety: 10 }

export interface ProjectRecord {
  id: string
  name: string
  data: ProjectData
  view: ProjectView
  revision: number
  createdAt: string
  updatedAt: string
}

export interface ProjectSummary {
  id: string
  name: string
  revision: number
  createdAt: string
  updatedAt: string
  llRules: number
  precSize: number
  snapshots: number
}

// auto: periodic backup while editing; named: saved by the user; safety: taken before a restore or an import.
export type SnapshotKind = 'auto' | 'named' | 'safety'

export interface SnapshotSummary {
  id: number
  label: string
  kind: SnapshotKind
  /** @deprecated use kind === 'auto' */
  auto: boolean
  createdAt: string
}

export type SaveResult =
  | { status: 'saved'; revision: number; updatedAt: string }
  | { status: 'conflict'; project: ProjectRecord }
  | { status: 'missing' }

export interface ProjectStore {
  listProjects(): ProjectSummary[]
  getProject(id: string): ProjectRecord | null
  createProject(name: string, data: unknown): ProjectRecord
  saveProject(id: string, data: unknown, baseRevision: number): SaveResult
  saveViewState(id: string, view: unknown): ProjectView | null
  replaceProjectData(id: string, data: unknown, label: string): ProjectRecord | null
  renameProject(id: string, name: string): ProjectRecord | null
  deleteProject(id: string): void
  duplicateProject(id: string): ProjectRecord | null
  listSnapshots(projectId: string): SnapshotSummary[]
  createSnapshot(projectId: string, label: string): SnapshotSummary | null
  restoreSnapshot(projectId: string, snapshotId: number): ProjectRecord | null
  deleteSnapshot(projectId: string, snapshotId: number): boolean
}

export interface StoreOptions {
  now?: () => Date
  newId?: () => string
}

interface ProjectRow {
  id: string
  name: string
  data: string
  view: string | null
  revision: number
  created_at: string
  updated_at: string
}

interface SnapshotRow {
  id: number
  label: string
  kind: SnapshotKind
  created_at: string
}

// Decodes any input into the current document shape and enforces the size cap.
function encodeData(input: unknown): string {
  const json = JSON.stringify(decodeProjectData(input))
  if (json.length > MAX_DATA_CHARS) throw new Error('Projekt je príliš veľký')
  return json
}

const parseJson = (json: string | null): unknown => {
  if (json === null) return undefined
  try {
    return JSON.parse(json)
  } catch {
    return undefined
  }
}

function requiredText(value: string, field: string, max: number) {
  const s = limitText(value, max)
  if (!s) throw new Error(`${field}: nesmie byť prázdny`)
  return s
}

const toRecord = (row: ProjectRow): ProjectRecord => ({
  id: row.id,
  name: row.name,
  data: decodeProjectData(parseJson(row.data)),
  view: row.view === null ? defaultProjectView() : decodeProjectView(parseJson(row.view)),
  revision: row.revision,
  createdAt: row.created_at,
  updatedAt: row.updated_at,
})

const toSnapshot = (row: SnapshotRow): SnapshotSummary => ({
  id: row.id,
  label: row.label,
  kind: row.kind,
  auto: row.kind === 'auto',
  createdAt: row.created_at,
})

export function createProjectStore(db: DatabaseSync, options: StoreOptions = {}): ProjectStore {
  const clock = options.now ?? (() => new Date())
  const now = () => clock().toISOString()
  const newId = options.newId ?? (() => randomBytes(8).toString('base64url'))
  const tx = <T>(fn: () => T) => transaction(db, fn)

  const findRow = (id: string) => db.prepare('SELECT * FROM projects WHERE id = ?').get(id) as ProjectRow | undefined
  const getProject = (id: string) => {
    const row = findRow(id)
    return row ? toRecord(row) : null
  }

  function insertProject(name: string, json: string, view: string | null): ProjectRecord {
    const id = newId()
    const ts = now()
    db.prepare('INSERT INTO projects (id, name, data, view, revision, created_at, updated_at) VALUES (?, ?, ?, ?, 1, ?, ?)').run(
      id,
      requiredText(name, 'Názov', PROJECT_NAME_MAX),
      json,
      view,
      ts,
      ts,
    )
    return getProject(id)!
  }

  // Inserts a snapshot and prunes older snapshots of the same kind (named versions are never pruned).
  function insertSnapshot(projectId: string, label: string, data: string, kind: SnapshotKind) {
    const info = db
      .prepare('INSERT INTO snapshots (project_id, label, kind, data, created_at) VALUES (?, ?, ?, ?, ?)')
      .run(projectId, requiredText(label, 'Popis', LABEL_MAX), kind, data, now())
    if (kind !== 'named') {
      db.prepare(
        `DELETE FROM snapshots WHERE project_id = ? AND kind = ? AND id NOT IN
           (SELECT id FROM snapshots WHERE project_id = ? AND kind = ? ORDER BY id DESC LIMIT ?)`,
      ).run(projectId, kind, projectId, kind, KEPT[kind])
    }
    return Number(info.lastInsertRowid)
  }

  // Overwrites the document, keeping the previous state as a safety snapshot.
  function replaceData(row: ProjectRow, json: string, label: string) {
    insertSnapshot(row.id, label, row.data, 'safety')
    db.prepare('UPDATE projects SET data = ?, revision = revision + 1, updated_at = ? WHERE id = ?').run(json, now(), row.id)
    return getProject(row.id)
  }

  const listSnapshots = (projectId: string) =>
    (
      db
        .prepare('SELECT id, label, kind, created_at FROM snapshots WHERE project_id = ? ORDER BY id DESC')
        .all(projectId) as unknown as SnapshotRow[]
    ).map(toSnapshot)

  return {
    listProjects() {
      const rows = db
        .prepare(
          `SELECT p.*, (SELECT COUNT(*) FROM snapshots s WHERE s.project_id = p.id) AS snapshot_count
           FROM projects p ORDER BY p.updated_at DESC`,
        )
        .all() as unknown as (ProjectRow & { snapshot_count: number })[]
      return rows.map((row) => {
        const data = decodeProjectData(parseJson(row.data))
        return {
          id: row.id,
          name: row.name,
          revision: row.revision,
          createdAt: row.created_at,
          updatedAt: row.updated_at,
          llRules: parseGrammar(data.ll.grammar).rules.length,
          // AI generated by: Claude Code / claude-opus-5-5
          // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
          // Changes: Table size (with $) from the precedence-table module.
          precSize: precTableSize(data.prec),
          snapshots: row.snapshot_count,
        }
      })
    },

    getProject,

    createProject: (name, data) => insertProject(name, encodeData(data), null),

    saveProject(id, data, baseRevision) {
      const json = encodeData(data)
      return tx((): SaveResult => {
        const row = findRow(id)
        if (!row) return { status: 'missing' }
        if (row.revision !== baseRevision) return { status: 'conflict', project: toRecord(row) }
        if (json === row.data) return { status: 'saved', revision: row.revision, updatedAt: row.updated_at }

        const lastAuto = db
          .prepare("SELECT created_at FROM snapshots WHERE project_id = ? AND kind = 'auto' ORDER BY id DESC LIMIT 1")
          .get(id) as { created_at: string } | undefined
        if (!lastAuto || clock().getTime() - Date.parse(lastAuto.created_at) >= AUTO_SNAPSHOT_EVERY_MS) {
          insertSnapshot(id, 'Automatická záloha', row.data, 'auto')
        }

        const ts = now()
        db.prepare('UPDATE projects SET data = ?, revision = revision + 1, updated_at = ? WHERE id = ?').run(json, ts, id)
        return { status: 'saved', revision: row.revision + 1, updatedAt: ts }
      })
    },

    saveViewState(id, view) {
      const decoded = decodeProjectView(view)
      const info = db.prepare('UPDATE projects SET view = ? WHERE id = ?').run(JSON.stringify(decoded), id)
      return info.changes ? decoded : null
    },

    replaceProjectData(id, data, label) {
      const json = encodeData(data)
      return tx(() => {
        const row = findRow(id)
        return row ? replaceData(row, json, label) : null
      })
    },

    renameProject(id, name) {
      db.prepare('UPDATE projects SET name = ? WHERE id = ?').run(requiredText(name, 'Názov', PROJECT_NAME_MAX), id)
      return getProject(id)
    },

    deleteProject(id) {
      db.prepare('DELETE FROM projects WHERE id = ?').run(id)
    },

    duplicateProject(id) {
      const row = findRow(id)
      if (!row) return null
      const name = `${limitText(row.name, PROJECT_NAME_MAX - ' (kópia)'.length)} (kópia)`
      return insertProject(name, encodeData(parseJson(row.data)), row.view)
    },

    listSnapshots,

    createSnapshot(projectId, label) {
      return tx(() => {
        const row = findRow(projectId)
        if (!row) return null
        const id = insertSnapshot(projectId, label, row.data, 'named')
        return listSnapshots(projectId).find((s) => s.id === id) ?? null
      })
    },

    restoreSnapshot(projectId, snapshotId) {
      return tx(() => {
        const snap = db.prepare('SELECT label, data FROM snapshots WHERE id = ? AND project_id = ?').get(snapshotId, projectId) as
          | { label: string; data: string }
          | undefined
        const row = findRow(projectId)
        if (!snap || !row) return null
        return replaceData(row, encodeData(parseJson(snap.data)), `Pred obnovením „${snap.label}“`)
      })
    },

    deleteSnapshot(projectId, snapshotId) {
      return db.prepare('DELETE FROM snapshots WHERE id = ? AND project_id = ?').run(snapshotId, projectId).changes > 0
    },
  }
}

// Production store: one lazily opened connection to TABLE_MAKER_DB (default data/table-maker.db).
let defaultStore: ProjectStore | undefined
export function projectStore(): ProjectStore {
  defaultStore ??= createProjectStore(openDatabase(process.env.TABLE_MAKER_DB ?? 'data/table-maker.db'))
  return defaultStore
}
